<script setup lang="ts">
import {localize} from './localization';

import {placementAnatomies} from '../../../packages/reference/placement-context';
import {placementReason} from './modules/mappingFeedback';
import {computed,ref,watch} from 'vue';
import {useSession} from './store';
import {bodyParts,partName,namedPart} from '../../../packages/reference/body-parts';
import type {Response} from '../../../packages/schema/index';
const props=defineProps<{language:'zh'|'en'}>(),store=useSession(),zh=computed(()=>props.language==='zh'),selected=ref<string[]>(bodyParts.filter(part=>part!=='unknown')),report=ref<Extract<Response,{ok:true}>['autoPlacementReport']>();
const regions=computed(()=>store.data.project?.patternLibrary??[]),chosen=computed(()=>regions.value.filter(r=>placementAnatomies(r).some(a=>selected.value.includes(a.part)))),unclassified=computed(()=>regions.value.filter(r=>!placementAnatomies(r).some(a=>a.part!=='unknown')).length),surface=computed(()=>store.data.project?.surface),parts=computed(()=>[...new Set(surface.value?.faces.map(f=>(surface.value?.partAssignments?.find(a=>a.region===f.region)??namedPart(f.region)).part)??[])]),pending=computed(()=>store.data.project?.markings?.filter(m=>m.placement&&!m.placement.reviewed&&!m.locked)??[]);
watch([()=>store.data.project?.id,()=>store.data.project?.surface?.id,()=>regions.value.map(r=>r.piece.id).join(',')],()=>{report.value=undefined;});
async function place(){const p=store.data.project;if(p)await store.run(async()=>{const r=await window.fpcad.autoPlaceMarkings(p.id,p.revision,chosen.value.map(r=>r.piece.id),[...selected.value] as typeof bodyParts[number][]);if(r.ok)report.value=r.autoPlacementReport;return r;});}
async function review(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'marking.placement.review',markingIds:pending.value.map(m=>m.id),reviewed:true}));}
async function cancel(){const p=store.data.project;if(p)await window.fpcad.cancelSurface(p.id,p.revision);}
const reason=(code:string)=>placementReason(code,zh.value);
</script>
<template><section class="auto-mapping" aria-label="按部位自动贴附"><h3>{{zh?'按部位自动贴附':localize('Automatic part placement')}}</h3><p>{{zh?'按正背视图与左右部位匹配；同部位花纹一起等比例缩放，手臂和腿按姿态旋转，保留配色与相对位置。缺失或未分类的部位会提示原因。':localize('Match front/back views and body sides. Scale a part’s colors together without stretching, rotate arms and legs to match the pose, and preserve relative positions. Missing or unclassified parts report a reason.')}}</p><p v-if="unclassified" class="review-note">{{unclassified}} {{zh?'个源区域仍待分类。可在花纹库核对部位，或拖到模型后调整尺寸与旋转。':'source regions still need classification. Review them in the library, or drag them onto the model and adjust size and rotation.'}}</p><small>{{zh?'模型当前部位':localize('Current model parts')}}: {{parts.map(p=>partName(p,zh)).join(' · ')||'—'}}</small><div class="part-options"><label v-for="part in bodyParts.filter(p=>regions.some(r=>placementAnatomies(r).some(a=>a.part===p)))" :key="part"><input v-model="selected" type="checkbox" :value="part">{{partName(part,zh)}} · {{regions.filter(r=>placementAnatomies(r).some(a=>a.part===part)).length}}</label></div><button class="primary" :disabled="store.busy||!surface||!chosen.length" @click="place">{{zh?'自动匹配并贴附所选部位':localize('Match and place selected parts')}} · {{chosen.length}}</button><button v-if="store.busy" @click="cancel">{{zh?'取消贴附':localize('Cancel placement')}}</button><p v-if="report" role="status">{{zh?'已贴附':localize('Placed')}} {{report.placed}} · {{zh?'跳过':localize('Skipped')}} {{report.skipped.length}}</p><p v-if="report?.skipped.length" class="review-note">{{zh?'自动贴附仅覆盖可见表面，跳过的花纹仍需分类或手动贴附。最后整体锁定前，请检查侧面和尾部。':localize('Automatic placement covers only visible surfaces. Classify skipped sources or attach them manually. Inspect side views and the tail before final locking.')}}</p><details v-if="report?.skipped.length" open><summary>{{zh?'查看未匹配原因':localize('Unmatched reasons')}}</summary><ul><li v-for="item in report.skipped" :key="item.pieceId+item.name">{{item.name}} — {{reason(item.reason)}}</li></ul></details><p v-if="pending.length" class="review-note">{{zh?'请旋转模型检查正面、背面和交界。自动位置未经确认前不能制造输出。':localize('Rotate and inspect the front, back and transitions. Unreviewed automatic placements cannot be manufactured.')}}</p><button v-if="pending.length" :disabled="store.busy" @click="review">{{zh?'已检查并确认自动贴附位置':localize('Approve reviewed automatic positions')}} · {{pending.length}}</button></section></template>
<style scoped>.auto-mapping{padding:15px;border-bottom:1px solid var(--border);font-size:12px}.auto-mapping p,.auto-mapping small{line-height:1.7;color:var(--text-muted)}.part-options{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0}.review-note{color:var(--warning)!important}.auto-mapping button{margin-bottom:8px;max-width:100%;white-space:normal}ul{padding-left:18px;max-height:180px;overflow:auto}li{margin:8px 0}</style>
